import math
from collections.abc import Mapping
from numbers import Real


def _vector(value, tuple_required=False):
    expected = tuple if tuple_required else (list, tuple)
    if not isinstance(value, expected):
        raise TypeError("invalid vector container")
    if not value:
        raise ValueError("vector must not be empty")
    result = []
    for number in value:
        if isinstance(number, bool) or not isinstance(number, Real):
            raise TypeError("vector entries must be real numbers")
        number = float(number)
        if not math.isfinite(number):
            raise ValueError("vector entries must be finite")
        result.append(number)
    return result


def train_centroids(samples):
    if not isinstance(samples, list):
        raise TypeError("samples must be a list")
    if not samples:
        raise ValueError("samples must not be empty")

    sums = {}
    counts = {}
    dimension = None
    for sample in samples:
        if not isinstance(sample, (list, tuple)) or len(sample) != 2:
            raise TypeError("each sample must be a pair")
        label, raw_vector = sample
        if not isinstance(label, str):
            raise TypeError("label must be a string")
        if not label:
            raise ValueError("label must not be empty")
        vector = _vector(raw_vector)
        if dimension is None:
            dimension = len(vector)
        elif len(vector) != dimension:
            raise ValueError("dimension mismatch")
        if label not in sums:
            sums[label] = [0.0] * dimension
            counts[label] = 0
        for index, number in enumerate(vector):
            sums[label][index] += number
        counts[label] += 1

    return {
        label: tuple(total / len(samples) for total in totals)
        for label, totals in sums.items()
    }


def predict(model, vector):
    if not isinstance(model, Mapping):
        raise TypeError("model must be a mapping")
    if not model:
        raise ValueError("model must not be empty")
    query = _vector(vector)
    centroids = []
    dimension = None
    for label, raw_centroid in model.items():
        if not isinstance(label, str):
            raise TypeError("label must be a string")
        if not label:
            raise ValueError("label must not be empty")
        centroid = _vector(raw_centroid, tuple_required=True)
        if dimension is None:
            dimension = len(centroid)
        elif len(centroid) != dimension:
            raise ValueError("dimension mismatch")
        centroids.append((label, centroid))
    if len(query) != dimension:
        raise ValueError("dimension mismatch")
    return min(
        centroids,
        key=lambda entry: (
            sum((a - b) ** 2 for a, b in zip(query, entry[1])),
            entry[0],
        ),
    )[0]

